      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n15만) 충청남,북도 거주) 만 18-27세 여성 청년 농부 1:1 ZOOM 인터뷰\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.11.25. 10:31\n조회 10\n구독\n15만) 충청남,북도 거주) 만 18-27세 청년 농부 1:1 ZOOM 인터뷰\n청년 농부 대상으로 1:1 화상회의(ZOOM) 참여자 모집 관련하여 메일드립니다.\n자세한 참여 조건은 아래와 같습니다.\n1. 성별무관\n2. 만 18-27세\n3. 시간대 자율(ZOOM 1:1 인터뷰 진행, 참여자에게 시간대 맞춰서 진행 예정)\n4. 사례비 15만원\n5. 충청남북도 청년 농부\nhttps://forms.gle/fZLLdQdJriLFeDnt7\n좋아요\n0\n송파구의 더 많은 인기글 보러가기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.11.25. 12:36 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n12/4~5) 30~40대 직장인 남성 ) 온라인 의사결정 실험 참여자 모집\n좌담회알바좌담회카페\n26.11.25.\n댓글\n2\n15만) 충청남,북도 거주) 만 18-27세 여성 청년 농부 1:1 ZOOM 인터뷰\n좌담회알바좌담회카페\n26.11.25.\n댓글\n1\n15만) 충청남,북도 거주) 남성 만 18-27세 청년 농부 1:1 ZOOM 인터뷰\n좌담회알바좌담회카페\n26.11.25.\n댓글\n1\n만 18-24세여성) 괴산/아산) AI와 함께하는 1:1 화상 줌 인터뷰\n좌담회알바좌담회카페\n26.11.25.\n댓글\n1\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
