      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n11/30~12/4) 20대 남녀) 금융앱사용성 조사 _ 최근1개월 내 주식거래 경험자 인터뷰(초보투자자, 단기투자자)\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.11.25. 13:23\n조회 98\n구독\n11/30~12/4) 20대 남녀) 금융앱사용성 조사 _ 최근1개월 내 주식거래 경험자 인터뷰(초보투자자, 단기투자자)\n신청하신분은 재신청 안하셔도 됩니다 ~\n주식거래 경험 인터뷰를 진행합니다.\n참석자 본인 휴대폰으로 앱을 직접 사용하는 모습을 평가할 예정입니다.\n인터뷰는 정규장 시간 내 (09:00~15:30)까지만 진행합니다.\n1G_초보투자자 _ 토스증권 OR 카카오페이증권 이용 (주식모으기. 또는 직접매수,매도 경험 필수) _월1회이상\n3G_단기투자자 _ 미래에셋증권 주이용 + 타 증권 주이용 _주2~3회이상\n* 인터뷰 일정 : 11/30(월)~12/4(금) 정규장내 시간\n* 인터뷰 장소 : 서울 강남구 신논현역\n* 인터뷰 소요시간 : 1시간30분이내\n* 인터뷰 사례비 : 사례비7만원 + 계좌투자5만원 =총12만원\n<신청 시 작성사항>\n- 신청 링크 내 소개자 이름을 작성할 수 있는 문항이 포함 되어있습니다. 아래의 링크에 작성 부탁드립니다.\n★★신청자에게 소개자명 작성 가이드 꼭 해주세요!! ★ ★\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\nhttps://ms.esurvey.kr/?ACCESS_KEY=b3855cd71d8340fea8a1\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\n좋아요\n0\n송파구에서 많이 본 동네소식 보러가기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.11.25. 14:35 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n11/30~12/4) 30대 남녀) 금융앱사용성 조사 _ 최근1개월 내 주식거래 경험자 인터뷰(초보투자자, 단기투자자)\n좌담회알바좌담회카페\n26.11.25.\n댓글\n2\n11/30~12/4) 20대 남녀) 금융앱사용성 조사 _ 최근1개월 내 주식거래 경험자 인터뷰(초보투자자, 단기투자자)\n좌담회알바좌담회카페\n26.11.25.\n댓글\n1\n11월26일 링크 발송~30일 마감)부산,대구,인천,광주,대전,울산 거주 여성 뷰티(화장품) 라이프 스타일 (온라인조사)\n좌담회알바좌담회카페\n26.11.25.\n댓글\n1\n11월26일 링크 발송~30일 마감) 경기도거주 여성 뷰티(화장품) 라이프 스타일 (온라인조사)\n좌담회알바좌담회카페\n26.11.25.\n댓글\n1\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
